begin;
create type public.release_information_state as enum('official_announced','retailer_confirmed','editorial_reported','rumor','released','restocked','cancelled','date_changed','unknown');
create table public.release_items(id uuid primary key default gen_random_uuid(),canonical_brand text not null,canonical_model_name text not null,model_family text not null,generation text,information_state public.release_information_state not null,release_date date,release_date_precision text not null default 'unknown' check(release_date_precision in('day','month','quarter','unknown')),region text not null default 'JP',source_confidence numeric(5,2) not null default 0 check(source_confidence between 0 and 100),first_seen_at timestamptz not null default now(),last_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.release_variants(id uuid primary key default gen_random_uuid(),release_item_id uuid not null references public.release_items(id) on delete cascade,colorway_name text,style_code text,audience public.sneaker_audience not null default 'unknown',region text not null default 'JP',verification_state text not null check(verification_state in('verified','model_only','unverified')));
create table public.release_evidence(id uuid primary key default gen_random_uuid(),release_item_id uuid not null references public.release_items(id) on delete cascade,source_kind text not null check(source_kind in('brand_official','authorized_retailer','editorial','manual')),source_url text,source_title text not null,supports_model boolean not null default false,supports_colorway boolean not null default false,supports_style_code boolean not null default false,fetched_at timestamptz not null default now(),source_quality numeric(5,2) not null check(source_quality between 0 and 100));
create index release_items_date_state_idx on public.release_items(release_date,information_state);create index release_variants_item_idx on public.release_variants(release_item_id);create index release_evidence_item_idx on public.release_evidence(release_item_id);
create table public.daily_pick_batches(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,target_date date not null,preference_version text not null,algorithm_version text not null,generated_at timestamptz not null default now(),unique(user_id,target_date,algorithm_version));
create table public.daily_picks(id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.daily_pick_batches(id) on delete cascade,release_item_id uuid not null references public.release_items(id),rank smallint not null check(rank between 1 and 8),total_score numeric(5,2) not null,score_breakdown jsonb not null check(jsonb_typeof(score_breakdown)='object'),explanation jsonb not null check(jsonb_typeof(explanation)='object'),verification_state text not null check(verification_state in('verified','model_only','unverified')),created_at timestamptz not null default now(),unique(batch_id,rank),unique(batch_id,release_item_id));
create table public.daily_pick_feedback(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,daily_pick_id uuid not null references public.daily_picks(id) on delete cascade,action text not null check(action in('saved','not_interested','wishlist','owned')),reason_codes text[] not null default '{}',comment text check(char_length(comment)<=500),created_at timestamptz not null default now());
create index daily_pick_batches_user_date_idx on public.daily_pick_batches(user_id,target_date desc);create index daily_pick_feedback_user_idx on public.daily_pick_feedback(user_id,created_at desc);
create trigger release_items_set_updated_at before update on public.release_items for each row execute function public.set_updated_at();
alter table public.release_items enable row level security;alter table public.release_variants enable row level security;alter table public.release_evidence enable row level security;alter table public.daily_pick_batches enable row level security;alter table public.daily_picks enable row level security;alter table public.daily_pick_feedback enable row level security;
create policy release_items_authenticated_read on public.release_items for select to authenticated using(true);create policy release_variants_authenticated_read on public.release_variants for select to authenticated using(true);create policy release_evidence_authenticated_read on public.release_evidence for select to authenticated using(true);
create policy daily_pick_batches_select_own on public.daily_pick_batches for select to authenticated using((select auth.uid())=user_id);
create policy daily_picks_select_own on public.daily_picks for select to authenticated using(exists(select 1 from public.daily_pick_batches b where b.id=batch_id and b.user_id=(select auth.uid())));
create policy daily_pick_feedback_own on public.daily_pick_feedback for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id and exists(select 1 from public.daily_picks p join public.daily_pick_batches b on b.id=p.batch_id where p.id=daily_pick_id and b.user_id=(select auth.uid())));
revoke all on public.release_items,public.release_variants,public.release_evidence,public.daily_pick_batches,public.daily_picks,public.daily_pick_feedback from anon;
grant select on public.release_items,public.release_variants,public.release_evidence,public.daily_pick_batches,public.daily_picks to authenticated;grant select,insert on public.daily_pick_feedback to authenticated;
commit;
